function dYdt = twoBody(~, Y, mu)
    % Y = [x, y, z, vx, vy, vz]
    rx = Y(1); ry = Y(2); rz = Y(3);
    vx = Y(4); vy = Y(5); vz = Y(6);

    r = sqrt(rx^2 + ry^2 + rz^2);
    accel = -mu / r^3 .* [rx; ry; rz];

    dYdt = [vx; vy; vz; accel(1); accel(2); accel(3)];
end



